import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Action Simulator Library","description":"","frontmatter":{},"headers":[],"relativePath":"features/actions.md","filePath":"features/actions.md"}'),o={name:"features/actions.md"};function r(n,e,c,l,d,h){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="action-simulator-library" tabindex="-1">Action Simulator Library <a class="header-anchor" href="#action-simulator-library" aria-label="Permalink to &quot;Action Simulator Library&quot;">​</a></h1><blockquote><p>Features 41–50</p></blockquote><p>AeroCI includes built-in realistic local simulations for popular GitHub Actions, enabling accurate pipeline execution without relying on external network services.</p><hr><h2 id="feature-41-—-actions-cache-simulator" tabindex="-1">Feature 41 — <code>actions/cache</code> Simulator <a class="header-anchor" href="#feature-41-—-actions-cache-simulator" aria-label="Permalink to &quot;Feature 41 — `actions/cache` Simulator&quot;">​</a></h2><p>Simulates key-based local caching using <code>.aeroci-artifacts/action-cache/</code>:</p><ul><li>Exact key matching &amp; <code>restore-keys</code> prefix matching</li><li>Local cache hit/miss simulation</li><li>Automatic cache persistence after job completion</li></ul><hr><h2 id="feature-42-—-actions-setup-python" tabindex="-1">Feature 42 — <code>actions/setup-python</code> <a class="header-anchor" href="#feature-42-—-actions-setup-python" aria-label="Permalink to &quot;Feature 42 — `actions/setup-python`&quot;">​</a></h2><p>Detects local Python installations (<code>python3</code> / <code>python</code>), matches requested version constraints, and configures environment variables.</p><hr><h2 id="feature-43-—-actions-setup-java" tabindex="-1">Feature 43 — <code>actions/setup-java</code> <a class="header-anchor" href="#feature-43-—-actions-setup-java" aria-label="Permalink to &quot;Feature 43 — `actions/setup-java`&quot;">​</a></h2><p>Detects local Java installations (<code>java -version</code>), verifies Java version &amp; distribution specs, and exports JDK environment variables.</p><hr><h2 id="feature-44-—-actions-setup-go" tabindex="-1">Feature 44 — <code>actions/setup-go</code> <a class="header-anchor" href="#feature-44-—-actions-setup-go" aria-label="Permalink to &quot;Feature 44 — `actions/setup-go`&quot;">​</a></h2><p>Detects local Go installations (<code>go version</code>) and verifies requested version compatibility.</p><hr><h2 id="feature-45-—-actions-github-script" tabindex="-1">Feature 45 — <code>actions/github-script</code> <a class="header-anchor" href="#feature-45-—-actions-github-script" aria-label="Permalink to &quot;Feature 45 — `actions/github-script`&quot;">​</a></h2><p>Executes inline JavaScript code provided in <code>with.script</code> within a sandboxed V8 context with mocked <code>github</code> and <code>core</code> octokit objects.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actions/github-script@v7</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      core.info(&#39;Executing inline script&#39;);</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      core.setOutput(&#39;status&#39;, &#39;success&#39;);</span></span></code></pre></div><hr><h2 id="feature-46-—-docker-build-push-action" tabindex="-1">Feature 46 — <code>docker/build-push-action</code> <a class="header-anchor" href="#feature-46-—-docker-build-push-action" aria-label="Permalink to &quot;Feature 46 — `docker/build-push-action`&quot;">​</a></h2><p>Validates Docker installation, verifies Dockerfile path existence, prints build metadata, and simulates image tag building without forcing remote registry pushes.</p><hr><h2 id="feature-47-—-actions-create-release" tabindex="-1">Feature 47 — <code>actions/create-release</code> <a class="header-anchor" href="#feature-47-—-actions-create-release" aria-label="Permalink to &quot;Feature 47 — `actions/create-release`&quot;">​</a></h2><p>Simulates release creation step, validating release tags, names, and body text, and outputting simulated release URLs.</p><hr><h2 id="feature-48-—-peaceiris-actions-gh-pages" tabindex="-1">Feature 48 — <code>peaceiris/actions-gh-pages</code> <a class="header-anchor" href="#feature-48-—-peaceiris-actions-gh-pages" aria-label="Permalink to &quot;Feature 48 — `peaceiris/actions-gh-pages`&quot;">​</a></h2><p>Simulates GitHub Pages deployment: validates source directory file contents, checks output branch configuration, and verifies custom domain CNAME settings.</p><hr><h2 id="feature-49-—-aws-actions-configure-aws-credentials" tabindex="-1">Feature 49 — <code>aws-actions/configure-aws-credentials</code> <a class="header-anchor" href="#feature-49-—-aws-actions-configure-aws-credentials" aria-label="Permalink to &quot;Feature 49 — `aws-actions/configure-aws-credentials`&quot;">​</a></h2><p>Audits AWS environment credentials (<code>AWS_ACCESS_KEY_ID</code>, <code>AWS_SECRET_ACCESS_KEY</code>, <code>AWS_REGION</code>) or OIDC <code>role-to-assume</code> parameters to ensure deployment readiness.</p><hr><h2 id="feature-50-—-action-marketplace-version-checker" tabindex="-1">Feature 50 — Action Marketplace Version Checker <a class="header-anchor" href="#feature-50-—-action-marketplace-version-checker" aria-label="Permalink to &quot;Feature 50 — Action Marketplace Version Checker&quot;">​</a></h2><p>Available via <code>aeroci versions</code>: checks action references across workflows against a maintained index of the latest stable action versions, flagging outdated actions and providing upgrade recommendations.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aeroci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> versions</span></span></code></pre></div>',36)])])}const k=a(o,[["render",r]]);export{p as __pageData,k as default};
